import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import api from '../../utils/api';

const STATUS_COLORS = { open: 'text-orange-500 bg-orange-500/20 border-orange-500/30', accepted: 'text-green-500 bg-green-500/20 border-green-500/30', expired: 'text-red-500 bg-red-500/20 border-red-500/30' };
const STATUS_LABELS = { open: '⏳ Waiting for restaurant', accepted: '✅ Accepted!', expired: '❌ Expired' };

export default function ReverseBidPage() {
  const navigate = useNavigate();
  const [tab, setTab] = useState('new'); // 'new' | 'my'
  const [desc, setDesc] = useState('');
  const [budget, setBudget] = useState('');
  const [address, setAddress] = useState('');
  const [dietNotes, setDietNotes] = useState('');
  const [placing, setPlacing] = useState(false);
  const [myBids, setMyBids] = useState([]);
  const [loadingBids, setLoadingBids] = useState(false);

  const loadMyBids = async () => {
    setLoadingBids(true);
    try {
      const res = await api.get('/features/bids/my');
      setMyBids(res.data);
    } catch (_) {}
    setLoadingBids(false);
  };

  useEffect(() => { 
    if (tab === 'my') loadMyBids(); 
  }, [tab]);

  const handlePlaceBid = async () => {
    if (!desc.trim()) return toast.error('Describe what you want');
    if (!budget || Number(budget) < 60) return toast.error('Minimum bid is ₹60');
    if (!address.trim()) return toast.error('Enter delivery address');

    setPlacing(true);
    try {
      await api.post('/features/bids', {
        description: desc,
        budget: Number(budget),
        address,
        dietaryNotes: dietNotes,
      });
      toast.success('🎯 Bid placed! Restaurants nearby are notified.');
      setDesc(''); setBudget(''); setAddress(''); setDietNotes('');
      setTab('my');
    } catch (e) {
      toast.error(e.response?.data?.message || 'Failed to place bid');
    } finally { 
      setPlacing(false); 
    }
  };

  return (
    <div className="min-h-screen bg-gray-900 text-white">
      <div className="bg-[#1a1a2a] p-8 text-center border-b border-gray-800">
        <div className="text-5xl mb-4">⚖️</div>
        <h1 className="text-2xl font-extrabold text-purple-500 mb-2">Reverse Bid</h1>
        <p className="text-gray-400 text-sm max-w-md mx-auto">
          Name your price. Restaurants race to accept during off-peak hours!
        </p>
      </div>

      <div className="max-w-xl mx-auto p-4 py-6">
        <div className="flex bg-gray-800 rounded-xl p-1 mb-6 border border-gray-700">
          <button 
            onClick={() => setTab('new')} 
            className={`flex-1 py-3 px-4 rounded-lg text-sm font-bold transition ${tab === 'new' ? 'bg-orange-500 text-white' : 'text-gray-400 hover:text-white'}`}
          >
            + New Bid
          </button>
          <button 
            onClick={() => setTab('my')} 
            className={`flex-1 py-3 px-4 rounded-lg text-sm font-bold transition ${tab === 'my' ? 'bg-orange-500 text-white' : 'text-gray-400 hover:text-white'}`}
          >
            📋 My Bids
          </button>
        </div>

        {tab === 'new' ? (
          <div className="space-y-6">
            <div className="space-y-2">
              <label className="block text-sm font-bold text-white">🍽️ What do you want?</label>
              <textarea
                className="w-full bg-gray-800 border border-gray-700 rounded-xl p-4 text-white placeholder-gray-500 focus:outline-none focus:border-purple-500 transition min-h-[80px]"
                placeholder="e.g. Spicy chicken sandwich, Paneer butter masala, etc."
                value={desc}
                onChange={(e) => setDesc(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <label className="block text-sm font-bold text-white">💰 Total Budget (₹) — incl. delivery</label>
              <input
                type="number"
                className="w-full bg-gray-800 border border-gray-700 rounded-xl p-4 text-white placeholder-gray-500 focus:outline-none focus:border-purple-500 transition"
                placeholder="e.g. 150"
                value={budget}
                onChange={(e) => setBudget(e.target.value)}
              />
              <p className="text-xs text-gray-500 mt-1">Min ₹60. Delivery fee (₹40) is included in your bid.</p>
            </div>

            <div className="space-y-2">
              <label className="block text-sm font-bold text-white">📍 Delivery Address</label>
              <textarea
                className="w-full bg-gray-800 border border-gray-700 rounded-xl p-4 text-white placeholder-gray-500 focus:outline-none focus:border-purple-500 transition min-h-[80px]"
                placeholder="Enter address"
                value={address}
                onChange={(e) => setAddress(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <label className="block text-sm font-bold text-white">🥗 Dietary Notes (optional)</label>
              <input
                type="text"
                className="w-full bg-gray-800 border border-gray-700 rounded-xl p-4 text-white placeholder-gray-500 focus:outline-none focus:border-purple-500 transition"
                placeholder="e.g. No onion, extra spicy, etc."
                value={dietNotes}
                onChange={(e) => setDietNotes(e.target.value)}
              />
            </div>

            <div className="bg-[#1a1a2a] border border-purple-500/40 rounded-xl p-5 mt-8 shadow-lg">
              <h3 className="text-purple-400 font-bold mb-3">How Bidding Works</h3>
              <ul className="space-y-2 text-sm text-gray-400">
                <li>⏰ Your bid is live for 30 minutes</li>
                <li>🏃 Nearby restaurants see your request in real-time</li>
                <li>🎯 First restaurant to accept wins the order</li>
                <li>📱 You get notified instantly when someone accepts</li>
              </ul>
            </div>

            <button
              onClick={handlePlaceBid}
              disabled={placing}
              className={`w-full mt-6 bg-purple-600 hover:bg-purple-700 text-white font-extrabold py-4 rounded-xl text-lg transition shadow-lg flex justify-center items-center ${
                placing ? 'opacity-70 cursor-not-allowed' : 'hover:scale-[1.02]'
              }`}
            >
              {placing ? <div className="animate-spin rounded-full h-6 w-6 border-t-2 border-white"></div> : '⚖️ Place My Bid'}
            </button>
            <div className="h-10"></div>
          </div>
        ) : (
          <div>
            {loadingBids ? (
              <div className="flex justify-center mt-12">
                <div className="animate-spin rounded-full h-10 w-10 border-t-2 border-orange-500"></div>
              </div>
            ) : myBids.length === 0 ? (
              <div className="flex flex-col items-center justify-center p-12 text-center">
                <div className="text-6xl mb-4">⚖️</div>
                <p className="text-gray-400 text-lg font-medium">No bids yet. Place your first bid!</p>
              </div>
            ) : (
              <div className="space-y-4">
                {myBids.map(item => (
                  <div key={item._id} className="bg-gray-800 rounded-xl p-5 border border-gray-700 shadow-xl">
                    <div className="flex justify-between items-start mb-3">
                      <h3 className="text-lg font-bold text-white flex-1 pr-4">{item.description}</h3>
                      <div className={`px-3 py-1 rounded-full text-xs font-bold border ${STATUS_COLORS[item.status]}`}>
                        {STATUS_LABELS[item.status]}
                      </div>
                    </div>

                    <p className="text-orange-500 font-bold mb-1">Budget: ₹{item.budget}</p>
                    {item.dietaryNotes && <p className="text-sm text-gray-400">📝 {item.dietaryNotes}</p>}
                    <p className="text-xs text-gray-500 mt-3 pt-3 border-t border-gray-700">Placed: {new Date(item.createdAt).toLocaleString()}</p>

                    {item.status === 'accepted' && item.orderId && (
                      <button 
                        onClick={() => navigate(`/track/${item.orderId}`)}
                        className="mt-4 w-full bg-orange-500 hover:bg-orange-600 text-white font-bold py-2 px-4 rounded-lg transition"
                      >
                        Track Order →
                      </button>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
